// SearchTweetsParams are the parameters for searching tweets.
type SearchTweetsParams struct {
	Query  string
	Limit  int32
	Offset int32
}

// SearchTweetsRow represents a search tweet row with rank.
type SearchTweetsRow struct {
	Tweet GetTweetByIDRow
	Rank  float64
}

// SearchTweets searches for tweets by content.
func (q *Queries) SearchTweets(ctx context.Context, arg SearchTweetsParams) ([]*SearchTweetsRow, error) {
	query := `
		SELECT t.*, 
		       ts_rank(to_tsvector('english', t.content), plainto_tsquery('english', $1)) AS rank
		FROM tweets t
		WHERE to_tsvector('english', t.content) @@ plainto_tsquery('english', $1)
		  AND t.deleted_at IS NULL
		ORDER BY rank DESC, t.created_at DESC
		LIMIT $2 OFFSET $3
	`
	rows, err := q.db.QueryContext(ctx, query, arg.Query, arg.Limit, arg.Offset)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var results []*SearchTweetsRow
	for rows.Next() {
		var row SearchTweetsRow
		if err := rows.Scan(
			&row.Tweet.ID, &row.Tweet.UserID, &row.Tweet.Content, pq.Array(&row.Tweet.MediaURLs),
			&row.Tweet.ParentTweetID, &row.Tweet.RetweetOfID, &row.Tweet.IsPoll,
			&row.Tweet.ViewCount, &row.Tweet.CreatedAt, &row.Tweet.UpdatedAt, &row.Tweet.DeletedAt, &row.Tweet.Metadata,
			&row.Rank,
		); err != nil {
			return nil, err
		}
		results = append(results, &row)
	}
	return results, rows.Err()
}

// GetTrendingHashtagsRow represents a trending hashtag row.
type GetTrendingHashtagsRow struct {
	Hashtag   string
	Count     int64
	FirstSeen time.Time
	LastSeen  time.Time
}

// GetTrendingHashtags retrieves trending hashtags.
func (q *Queries) GetTrendingHashtags(ctx context.Context, limit int32) ([]*GetTrendingHashtagsRow, error) {
	query := `
		SELECT 
			LOWER(SUBSTRING(t.content FROM '#([A-Za-z0-9_]+)')) AS hashtag,
			COUNT(*) AS count,
			MIN(t.created_at) AS first_seen,
			MAX(t.created_at) AS last_seen
		FROM tweets t
		WHERE t.content ~ '#[A-Za-z0-9_]+'
		  AND t.created_at > NOW() - INTERVAL '24 hours'
		  AND t.deleted_at IS NULL
		GROUP BY hashtag
		ORDER BY count DESC
		LIMIT $1
	`
	rows, err := q.db.QueryContext(ctx, query, limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var results []*GetTrendingHashtagsRow
	for rows.Next() {
		var row GetTrendingHashtagsRow
		if err := rows.Scan(&row.Hashtag, &row.Count, &row.FirstSeen, &row.LastSeen); err != nil {
			return nil, err
		}
		results = append(results, &row)
	}
	return results, rows.Err()
}

