// GetMostLikedTweets retrieves the most liked tweets.
func (q *Queries) GetMostLikedTweets(ctx context.Context, arg GetMostLikedTweetsParams) ([]*GetMostLikedTweetsRow, error) {
	query := `
		SELECT t.*, COUNT(l.id) AS like_count
		FROM tweets t
		LEFT JOIN likes l ON t.id = l.tweet_id
		WHERE t.deleted_at IS NULL
		  AND t.created_at > $1
		GROUP BY t.id
		ORDER BY like_count DESC, t.created_at DESC
		LIMIT $2
	`
	rows, err := q.db.QueryContext(ctx, query, arg.Since, arg.Limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var results []*GetMostLikedTweetsRow
	for rows.Next() {
		var row GetMostLikedTweetsRow
		if err := rows.Scan(
			&row.Tweet.ID, &row.Tweet.UserID, &row.Tweet.Content, pq.Array(&row.Tweet.MediaURLs),
			&row.Tweet.ParentTweetID, &row.Tweet.RetweetOfID, &row.Tweet.IsPoll,
			&row.Tweet.ViewCount, &row.Tweet.CreatedAt, &row.Tweet.UpdatedAt, &row.Tweet.DeletedAt, &row.Tweet.Metadata,
			&row.LikeCount,
		); err != nil {
			return nil, err
		}
		results = append(results, &row)
	}
	return results, rows.Err()
}

