// AreMutual checks if two users are mutual follows.
func (q *Queries) AreMutual(ctx context.Context, user1ID, user2ID string) (bool, error) {
	query := `
		SELECT EXISTS(
			SELECT 1 FROM follows f1
			JOIN follows f2 ON f1.followee_id = f2.follower_id
			WHERE f1.follower_id = $1 AND f2.followee_id = $2
		)
	`
	var exists bool
	err := q.db.QueryRowContext(ctx, query, user1ID, user2ID).Scan(&exists)
	return exists, err
}

// GetFollowRecommendationsParams are the parameters for getting follow recommendations.
type GetFollowRecommendationsParams struct {
	UserID string
	Limit  int32
}

// GetFollowRecommendations retrieves follow recommendations for a user.
func (q *Queries) GetFollowRecommendations(ctx context.Context, arg GetFollowRecommendationsParams) ([]string, error) {
	query := `
		SELECT DISTINCT f2.followee_id
		FROM follows f1
		JOIN follows f2 ON f1.followee_id = f2.follower_id
		WHERE f1.follower_id = $1
		  AND f2.followee_id != $1
		  AND f2.followee_id NOT IN (
		    SELECT followee_id FROM follows WHERE follower_id = $1
		  )
		ORDER BY RANDOM()
		LIMIT $2
	`
	rows, err := q.db.QueryContext(ctx, query, arg.UserID, arg.Limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var ids []string
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		ids = append(ids, id)
	}
	return ids, rows.Err()
}

