// GetConversationsRow represents a conversation row.
type GetConversationsRow struct {
	OtherUserID       string
	LastMessageAt     time.Time
	LastMessageID     string
	LastMessageContent string
	LastMessageRead   bool
	UnreadCount       int
}

// GetConversations retrieves all conversations for a user.
func (q *Queries) GetConversations(ctx context.Context, userID string) ([]*GetConversationsRow, error) {
	query := `
		SELECT 
			CASE 
				WHEN sender_id = $1 THEN receiver_id
				WHEN receiver_id = $1 THEN sender_id
			END AS other_user_id,
			MAX(created_at) AS last_message_at,
			(SELECT id FROM messages m2 
			 WHERE (m2.sender_id = $1 AND m2.receiver_id = other_user_id)
				OR (m2.sender_id = other_user_id AND m2.receiver_id = $1)
			   AND m2.deleted_at IS NULL
			 ORDER BY m2.created_at DESC LIMIT 1) AS last_message_id,
			(SELECT content FROM messages m3 WHERE m3.id = last_message_id) AS last_message_content,
			(SELECT read FROM messages m3 WHERE m3.id = last_message_id) AS last_message_read,
			COUNT(CASE WHEN read = false AND receiver_id = $1 THEN 1 END) AS unread_count
		FROM messages
		WHERE (sender_id = $1 OR receiver_id = $1)
		  AND deleted_at IS NULL
		GROUP BY other_user_id
		ORDER BY last_message_at DESC
	`
	rows, err := q.db.QueryContext(ctx, query, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var results []*GetConversationsRow
	for rows.Next() {
		var row GetConversationsRow
		if err := rows.Scan(
			&row.OtherUserID, &row.LastMessageAt, &row.LastMessageID,
			&row.LastMessageContent, &row.LastMessageRead, &row.UnreadCount,
		); err != nil {
			return nil, err
		}
		results = append(results, &row)
	}
	return results, rows.Err()
}

