// AddCommunityMember adds a member to a community.
func (q *Queries) AddCommunityMember(ctx context.Context, communityID, userID, role string) error {
	query := `INSERT INTO community_members (community_id, user_id, role, joined_at) VALUES ($1, $2, $3, NOW())`
	_, err := q.db.ExecContext(ctx, query, communityID, userID, role)
	if err != nil {
		return err
	}
	// Increment member count
	_, err = q.db.ExecContext(ctx, `UPDATE communities SET member_count = member_count + 1 WHERE id = $1`, communityID)
	return err
}

// RemoveCommunityMember removes a member from a community.
func (q *Queries) RemoveCommunityMember(ctx context.Context, communityID, userID string) error {
	query := `DELETE FROM community_members WHERE community_id = $1 AND user_id = $2`
	_, err := q.db.ExecContext(ctx, query, communityID, userID)
	if err != nil {
		return err
	}
	// Decrement member count
	_, err = q.db.ExecContext(ctx, `UPDATE communities SET member_count = GREATEST(member_count - 1, 0) WHERE id = $1`, communityID)
	return err
}

// UpdateCommunityMemberRole updates a member's role.
func (q *Queries) UpdateCommunityMemberRole(ctx context.Context, communityID, userID, role string) error {
	query := `UPDATE community_members SET role = $1, updated_at = NOW() WHERE community_id = $2 AND user_id = $3`
	_, err := q.db.ExecContext(ctx, query, role, communityID, userID)
	return err
}

// GetCommunityMemberRole gets a member's role.
func (q *Queries) GetCommunityMemberRole(ctx context.Context, communityID, userID string) (string, error) {
	query := `SELECT role FROM community_members WHERE community_id = $1 AND user_id = $2`
	var role string
	err := q.db.QueryRowContext(ctx, query, communityID, userID).Scan(&role)
	return role, err
}

// IsCommunityMember checks if a user is a member of a community.
func (q *Queries) IsCommunityMember(ctx context.Context, communityID, userID string) (bool, error) {
	query := `SELECT EXISTS(SELECT 1 FROM community_members WHERE community_id = $1 AND user_id = $2)`
	var exists bool
	err := q.db.QueryRowContext(ctx, query, communityID, userID).Scan(&exists)
	return exists, err
}

// IsCommunityAdmin checks if a user is an admin of a community.
func (q *Queries) IsCommunityAdmin(ctx context.Context, communityID, userID string) (bool, error) {
	query := `SELECT EXISTS(SELECT 1 FROM community_members WHERE community_id = $1 AND user_id = $2 AND role IN ('admin', 'owner'))`
	var exists bool
	err := q.db.QueryRowContext(ctx, query, communityID, userID).Scan(&exists)
	return exists, err
}

